BEGIN; SET LOCAL lock_timeout='3s'; SET LOCAL statement_timeout='20s'; SELECT pg_advisory_xact_lock(714024,3);
DO $activate$ DECLARE deadline timestamptz:='__P5_FIXED_WINDOW_DEADLINE__'::timestamptz; scope jsonb:='{"family":"P5","tripId":"825f79b2-4a9d-4535-a62e-43000ca50c4a","sourceId":"58622bc1-fb9c-47ae-8e56-5a289ad217fa","batchId":"6a8ee6be-88a3-4f91-8a1e-2881d5409b23","taskId":"43c79b67-519e-8828-8854-c076356c6a45","token":"i1","resultSha256":"ecdb84fc4c5d830dec1f2d3a449808024a2192aaa7bacc0420d1aea89ca4c082","candidateId":"94f2ab9e-fb01-80b5-a759-96c4850d8af7","targetId":"7151caa5-4d9a-89db-b033-89d6f71deda5","operationId":"3f9e8b09-0ea2-8a4d-8b4c-de9aec316e8d","slotId":"fbb1c9dc-b6c2-8f63-b596-8a6af651e5a6","title":"Coastal QA Train","localDate":"2026-11-03","operatorLiteral":"Coastal QA Rail","serviceNumber":"CQ101"}'::jsonb; BEGIN
 IF deadline<=clock_timestamp() OR deadline>clock_timestamp()+interval '3600 seconds' THEN RAISE EXCEPTION 'P5_INVALID_DEADLINE';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.trip_sustained_dev_policy WHERE actor_account_id='f4b059c5-8241-4ffb-aa15-37fa25474543'::uuid AND enabled AND revoked_at IS NULL AND NOT universal_p1_import_enabled AND universal_p1_review_scope IS NULL) THEN RAISE EXCEPTION 'P5_POLICY_DRIFT';END IF;
 IF EXISTS(SELECT 1 FROM public.trip_source_core_v2_candidates WHERE candidate_id=(scope->>'candidateId')::uuid)
 OR EXISTS(SELECT 1 FROM public.itinerary_events WHERE id=(scope->>'targetId')::uuid)
 OR EXISTS(SELECT 1 FROM public.trip_core_command_receipts WHERE operation_id=(scope->>'operationId')::uuid) THEN RAISE EXCEPTION 'P5_ALREADY_STARTED_RECONCILE_ONLY';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.trip_sources WHERE id=(scope->>'sourceId')::uuid AND trip_id=(scope->>'tripId')::uuid AND acquired_by='f4b059c5-8241-4ffb-aa15-37fa25474543'::uuid AND lifecycle='ACTIVE' AND retention_state='RETAINED' AND current_material_revision=1)
 OR NOT EXISTS(SELECT 1 FROM public.trip_source_runs WHERE id='5edc5aeb-e3a2-8649-9bb9-4fd9b3ac9ee5' AND actor_account_id='f4b059c5-8241-4ffb-aa15-37fa25474543'::uuid AND trip_id=(scope->>'tripId')::uuid AND capture_batch_id=(scope->>'batchId')::uuid AND interpretation_task_id=(scope->>'taskId')::uuid AND state='PENDING' AND retention_state='RETAINED' AND superseded_by IS NULL) THEN RAISE EXCEPTION 'P5_SOURCE_STALE';END IF;
IF md5(pg_get_functiondef('public.trip_core_guard_historical_source_association()'::regprocedure)) IS DISTINCT FROM '93801f3fadf5dba7a6214561642fe436' THEN RAISE EXCEPTION 'P5_FUNCTION_DRIFT';END IF;
IF md5(pg_get_functiondef('public.trip_sustained_import_p1_capabilities(uuid,uuid)'::regprocedure)) IS DISTINCT FROM '1079d0aab7b396055ea96c98bf0fe96d' THEN RAISE EXCEPTION 'P5_FUNCTION_DRIFT';END IF;
IF md5(pg_get_functiondef('public.trip_sustained_import_p1_guard(text,text,jsonb,jsonb,uuid,uuid)'::regprocedure)) IS DISTINCT FROM '1276642cf7fcd0ae5be4be2934e79ee1' THEN RAISE EXCEPTION 'P5_FUNCTION_DRIFT';END IF;
IF md5(pg_get_functiondef('public.trip_core_service_statement_guard()'::regprocedure)) IS DISTINCT FROM '114c66014850ca45c288752f39a11370' THEN RAISE EXCEPTION 'P5_FUNCTION_DRIFT';END IF;
 UPDATE public.trip_sustained_dev_policy SET universal_p1_import_enabled=true,universal_p1_review_scope=scope||jsonb_build_object('expiresAt',deadline) WHERE actor_account_id='f4b059c5-8241-4ffb-aa15-37fa25474543'::uuid;
END $activate$;
COMMIT;
